const adminSearchTayfas = `-- name: AdminSearchTayfas :many

SELECT t.id, t.name, t.status, t.visibility, t.created_at, t.suspended_at, t.deleted_at,
       t.deletion_scheduled_for,
       (SELECT count(*) FROM memberships m WHERE m.tayfa_id = t.id AND m.status = 'active')::int AS member_count
FROM tayfas t
WHERE t.name_normalized LIKE '%' || $1::text || '%' ESCAPE '\'
ORDER BY t.created_at DESC, t.id DESC
LIMIT 50
`

type AdminSearchTayfasRow struct {
	ID                   pgtype.UUID
	Name                 string
	Status               string
	Visibility           string
	CreatedAt            pgtype.Timestamptz
	SuspendedAt          pgtype.Timestamptz
	DeletedAt            pgtype.Timestamptz
	DeletionScheduledFor pgtype.Timestamptz
	MemberCount          int32
}

// Platform yönetim paneli (issue #104 2. aşama, ADR-0008). Yalnızca
// internal/core/app/admin kullanır; her çağrıdan önce admin token'ı ve
// identity'nin yöneticilik onayı denetlenir. Panelin göremedikleri burada
// seçilmez: konum (buluşma noktası, av koordinatı), anket oyları, tayfa
// içeriği (yalnızca şikâyet edilen öğe tek tek okunur).
func (q *Queries) AdminSearchTayfas(ctx context.Context, pattern string) ([]AdminSearchTayfasRow, error) {
	rows, err := q.db.Query(ctx, adminSearchTayfas, pattern)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []AdminSearchTayfasRow{}
	for rows.Next() {
		var i AdminSearchTayfasRow
		if err := rows.Scan(
			&i.ID,
			&i.Name,
			&i.Status,
			&i.Visibility,
			&i.CreatedAt,
			&i.SuspendedAt,
			&i.DeletedAt,
			&i.DeletionScheduledFor,
			&i.MemberCount,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

